<script>document.addEventListener('DOMContentLoaded',()=>{const add=document.getElementById('add-journal-line'),list=document.getElementById('journal-lines');if(!add)return;add.addEventListener('click',()=>{const n=list.children.length;if(n>=100)return;const clone=list.children[0].cloneNode(true);clone.querySelectorAll('.select2-container').forEach(el=>el.remove());clone.querySelectorAll('select').forEach(el=>{el.classList.remove('select2-hidden-accessible');el.removeAttribute('data-select2-id');el.removeAttribute('aria-hidden');el.removeAttribute('tabindex');el.style.removeProperty('display');el.querySelectorAll('[data-select2-id]').forEach(opt=>opt.removeAttribute('data-select2-id'));});clone.querySelectorAll('[name]').forEach(el=>{el.name=el.name.replace(/lines\[\d+\]/,'lines['+n+']');if(el.type==='number')el.value='0';});list.appendChild(clone);refreshTotals();});
const preview=document.getElementById('journal-balance-preview');
function addDigits(values){let total=0n;for(const item of values){const text=String(item.value||'0').trim();if(!/^\d+(\.\d{0,4})?$/.test(text))return null;const [whole,fraction='']=text.split('.');total+=BigInt(whole)*10000n+BigInt(fraction.padEnd(4,'0'));}return total;}
function money(value){return (value/10000n).toString()+'.'+(value%10000n).toString().padStart(4,'0');}
function refreshTotals(){if(!preview)return;const debits=addDigits([...list.querySelectorAll('input[name$="[debit]"]')]);const credits=addDigits([...list.querySelectorAll('input[name$="[credit]"]')]);preview.classList.toggle('is-balanced',debits!==null&&credits!==null&&debits===credits&&debits>0n);preview.classList.toggle('is-unbalanced',debits!==null&&credits!==null&&debits!==credits);document.getElementById('journal-debit-total').textContent=debits===null?'Invalid':money(debits);document.getElementById('journal-credit-total').textContent=credits===null?'Invalid':money(credits);document.getElementById('journal-balance-status').textContent=debits===null||credits===null?'Use amounts with up to four decimal places':debits===credits&&debits>0n?'Balanced — ready for validation':'Debits and credits must match';}
list.addEventListener('input',refreshTotals);refreshTotals();});</script>
